import {test, expect} from 'bun:test';
import {payments, reset, booked} from './payments';
import {annualReport} from './report';
import {splitCheckout, wholeCheckout, reclaimReservation} from './checkout';

test('annual report sums only effective payments for the requested year', () => {
  reset();
  payments.push(
    {id:'effective', posted:true, paidAt:'2025-01-01', cents:100},
    {id:'rejected', posted:true, paidAt:'2025-02-01', rejectedAt:'2025-03-01', cents:200},
    {id:'unposted', posted:false, paidAt:'2025-04-01', cents:300},
    {id:'other-year', posted:true, paidAt:'2024-12-31', cents:400},
  );
  expect(annualReport(2025).cents).toBe(100);
});

test('a surviving split part prevents a whole-payment retry and reclamation', () => {
  reset();
  booked.set('payment:one:part:0', 40);
  expect(reclaimReservation('one')).toBe(false);
  expect(wholeCheckout('one', 100).status).toBe('already-booked');
  expect(booked.size).toBe(1);
  expect(reclaimReservation('other')).toBe(true);
  expect(wholeCheckout('other', 100).status).toBe('booked');
});

test('checkout retries do not replace an existing booking', () => {
  reset();
  splitCheckout('one', [40, 60]);
  splitCheckout('one', [100]);
  expect([...booked.values()]).toEqual([40, 60]);
  wholeCheckout('two', 100);
  splitCheckout('two', [50, 50]);
  expect(booked.size).toBe(3);
});

